import java.util.Objects;

class TreeNode<T> {
    T value;
    TreeNode<T> left;
    TreeNode<T> right;

    TreeNode(T value) {
        this.value = value;
        this.left = null;
        this.right = null;
    }
}

public class TreeRotator {
    /** 
     * Performs a right node rotation.
     * @param node a node to rotate
     * @return a new parent of the {@code node}
     */
    private TreeNode<T> rotateRight(TreeNode<T> node) {
        Objects.requireNonNull(node, "Node cannot be null");
        TreeNode<T> newParent = node.left;
        if (newParent == null) {
            return node; // No left child to rotate with
        }
        TreeNode<T> newParentRight = newParent.right;
        newParent.right = node;
        node.left = newParentRight;
        return newParent;
    }

    public static void main(String[] args) {
        // Example usage
        TreeRotator rotator = new TreeRotator();
        TreeNode<Integer> root = new TreeNode<>(3);
        root.left = new TreeNode<>(2);
        root.left.left = new TreeNode<>(1);

        System.out.println("Before rotation, root value: " + root.value);
        TreeNode<Integer> newRoot = rotator.rotateRight(root);
        System.out.println("After rotation, new root value: " + newRoot.value);
    }
}
