import java.util.Map;
import org.jgrapht.Graph;
import org.jgrapht.graph.DefaultEdge;
import org.jgrapht.graph.SimpleGraph;

public class BipartiteGraphGenerator<V, E extends DefaultEdge> {

    @Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        if (resultMap == null || resultMap.size() < 2) {
            throw new IllegalArgumentException("Result map must contain at least two vertices.");
        }

        // Split the vertices into two sets
        int size = resultMap.size();
        V[] vertices = resultMap.values().toArray((V[]) new Object[size]);
        int mid = size / 2;

        // Add edges between the two sets
        for (int i = 0; i < mid; i++) {
            for (int j = mid; j < size; j++) {
                target.addEdge(vertices[i], vertices[j]);
            }
        }
    }

    public static void main(String[] args) {
        Graph<String, DefaultEdge> graph = new SimpleGraph<>(DefaultEdge.class);
        Map<String, String> resultMap = Map.of(
            "A", "A", "B", "B", "C", "C", // First set
            "X", "X", "Y", "Y", "Z", "Z"  // Second set
        );

        BipartiteGraphGenerator<String, DefaultEdge> generator = new BipartiteGraphGenerator<>();
        generator.generateGraph(graph, resultMap);

        // Print the edges to verify
        graph.edgeSet().forEach(edge -> 
            System.out.println(graph.getEdgeSource(edge) + " - " + graph.getEdgeTarget(edge))
        );
    }
}
