import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;

public class TypeResolver {

    /** 
     * Resolves the arguments for the  {@code genericType} using the type variable information for the{@code targetType}. Returns  {@code null} if {@code genericType} is not parameterized or ifarguments cannot be resolved.
     */
    public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }

        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

        if (actualTypeArguments.length == 0) {
            return null;
        }

        TypeVariable<?>[] typeVariables = targetType.getTypeParameters();
        Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

        for (int i = 0; i < actualTypeArguments.length; i++) {
            if (actualTypeArguments[i] instanceof Class) {
                resolvedArguments[i] = (Class<?>) actualTypeArguments[i];
            } else if (actualTypeArguments[i] instanceof TypeVariable) {
                for (int j = 0; j < typeVariables.length; j++) {
                    if (typeVariables[j].equals(actualTypeArguments[i])) {
                        // This is a simple implementation and does not handle complex cases like bounds or multiple levels of generics
                        resolvedArguments[i] = null;
                        break;
                    }
                }
            } else {
                resolvedArguments[i] = null;
            }
        }

        return resolvedArguments;
    }

    public static void main(String[] args) {
        // Example usage
        Type genericType = new ParameterizedType() {
            @Override
            public Type[] getActualTypeArguments() {
                return new Type[]{String.class, Integer.class};
            }

            @Override
            public Type getRawType() {
                return Object.class;
            }

            @Override
            public Type getOwnerType() {
                return null;
            }
        };

        Class<?>[] resolved = resolveArguments(genericType, ExampleClass.class);
        if (resolved != null) {
            for (Class<?> clazz : resolved) {
                System.out.println(clazz);
            }
        } else {
            System.out.println("Arguments could not be resolved.");
        }
    }
}

class ExampleClass<T, U> {
