public class MetricsCache<METRICS extends Map<String, Integer>> {
    private final Map<String, Integer> cache = new HashMap<>();

    /** 
     * Accept the data into the cache and merge with the existing value. This method is not thread safe, should avoid concurrency calling.
     * @param data to be added potentially.
     */
    @Override
    public void accept(final METRICS data) {
        for (Map.Entry<String, Integer> entry : data.entrySet()) {
            cache.merge(entry.getKey(), entry.getValue(), Integer::sum);
        }
    }

    public Map<String, Integer> getCache() {
        return cache;
    }

    public static void main(String[] args) {
        MetricsCache<HashMap<String, Integer>> metricsCache = new MetricsCache<>();
        HashMap<String, Integer> data1 = new HashMap<>();
        data1.put("metric1", 10);
        data1.put("metric2", 20);

        HashMap<String, Integer> data2 = new HashMap<>();
        data2.put("metric1", 5);
        data2.put("metric3", 15);

