    private LinkedList<Bucket> list;

    public Bucket(int value, LinkedList<Bucket> list) {
        this.value = value;
        this.list = list;
    }

    /** 
     * Inserts this bucket in the data structure before the  {@code bucket}.
     * @param bucket the bucket, that will be the next to this bucket.
     */
    void insertBefore(Bucket bucket) {
        if (list == null || bucket == null) {
            return;
        }
        int index = list.indexOf(bucket);
        if (index != -1) {
            list.add(index, this);
        }
    }

    @Override
    public String toString() {
        return "Bucket{" +
                "value=" + value +
                '}';
    }

    public static void main(String[] args) {
        LinkedList<Bucket> list = new LinkedList<>();
        Bucket bucket1 = new Bucket(1, list);
        Bucket bucket2 = new Bucket(2, list);
        Bucket bucket3 = new Bucket(3, list);

        list.add(bucket1);
        list.add(bucket3);

        bucket2.insertBefore(bucket3);

        System.out.println(list); // Output: [Bucket{value=1}, Bucket{value=2}, Bucket{value=3}]
