import java.util.ArrayDeque;
import java.util.Queue;

public class LoggingEventBuffer {
    private final Queue<LoggingEvent> buffer;
    private final int capacity;

    public LoggingEventBuffer(int capacity) {
        this.capacity = capacity;
        this.buffer = new ArrayDeque<>(capacity);
    }

    /** 
     * Place a  {@link LoggingEvent} in the buffer. If the buffer is full then the event is <b>silently dropped</b>. It is the caller's responsability to make sure that the buffer has free space.  
     */
    public void put(LoggingEvent o) {
        if (buffer.size() < capacity) {
            buffer.add(o);
        }
    }

    public static void main(String[] args) {
