import java.util.Stack;

public class FrameStackManager {
    private Stack<String> outputFrameStack;

    public FrameStackManager() {
        this.outputFrameStack = new Stack<>();
    }

    /** 
     * Pops as many abstract types from the output frame stack as described by the given descriptor.
     * @param descriptor a type or method descriptor (in which case its argument types are popped).
     */
    private void pop(final String descriptor) {
        if (descriptor == null || descriptor.isEmpty()) {
            return;
        }

        int index = 0;
        while (index < descriptor.length()) {
            char c = descriptor.charAt(index);
            switch (c) {
                case 'B': case 'C': case 'D': case 'F': case 'I': case 'J': case 'S': case 'Z':
                    outputFrameStack.pop();
                    index++;
                    break;
                case 'L':
                    // Consume the entire class name
                    while (descriptor.charAt(index) != ';') {
                        index++;
                    }
                    outputFrameStack.pop();
                    index++; // Move past the ';'
                    break;
                case '[':
                    // Consume the array dimensions
                    while (descriptor.charAt(index) == '[') {
                        index++;
                    }
                    // The next character should be a type descriptor
                    if (descriptor.charAt(index) == 'L') {
                        while (descriptor.charAt(index) != ';') {
                            index++;
                        }
                    }
                    outputFrameStack.pop();
                    index++; // Move past the type descriptor
                    break;
                case '(':
                    // Method descriptor, pop each argument type
                    index++;
                    while (descriptor.charAt(index) != ')') {
                        pop(String.valueOf(descriptor.charAt(index)));
                        index++;
                    }
                    index++; // Move past the ')'
                    break;
                default:
                    index++;
                    break;
            }
        }
    }

    public static void main(String[] args) {
        FrameStackManager manager = new FrameStackManager();
        // Example usage
        manager.outputFrameStack.push("int");
        manager.outputFrameStack.push("double");
        manager.outputFrameStack.push("java/lang/String");
        manager.pop("(IDLjava/lang/String;)V");
        System.out.println(manager.outputFrameStack); // Should be empty
    }
}
