public class BoxSplitter {

    public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
        Vec2 position = box.getPosition();
        float width = box.getWidth();
        float height = box.getHeight();

        float halfWidth = width / 2.0f;

        Box2D leftBox = new Box2D(position.x - halfWidth / 2.0f, position.y, halfWidth, height);
        Box2D rightBox = new Box2D(position.x + halfWidth / 2.0f, position.y, halfWidth, height);

        return new Pair<>(leftBox, rightBox);
    }

    // Assuming Box2D is a custom class representing a box with position, width, and height
    public static class Box2D {
        private Vec2 position;
        private float width;
        private float height;

        public Box2D(float x, float y, float width, float height) {
            this.position = new Vec2(x, y);
            this.width = width;
            this.height = height;
        }

        public Vec2 getPosition() {
            return position;
        }

        public float getWidth() {
            return width;
        }

        public float getHeight() {
            return height;
        }
    }

    public static void main(String[] args) {
        Box2D box = new Box2D(0, 0, 4, 2);
        Pair<Box2D, Box2D> splitBoxes = splitAlongXAxis(box);
