    public Graph() {
        edges = new java.util.HashMap<>();
    }

    public void addEdge(V from, V to, double weight) {
        edges.computeIfAbsent(from, k -> new java.util.HashMap<>()).put(to, weight);
    }

    /** 
     * Compute the sum of the weights entering a vertex
     * @param v the vertex
     * @return the sum of the weights entering a vertex
     */
    public double vertexWeight(V v) {
        double sum = 0.0;
        for (Map<V, Double> entrySet : edges.values()) {
            if (entrySet.containsKey(v)) {
                sum += entrySet.get(v);
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        Graph<String, String> graph = new Graph<>();
        graph.addEdge("A", "B", 1.0);
        graph.addEdge("C", "B", 2.0);
        graph.addEdge("B", "D", 3.0);
        System.out.println(graph.vertexWeight("B")); // Output should be 3.0
