public class CharacterUtils {
    /** 
     * <p>Converts an array of object Characters to primitives.</p> <p>This method returns <code>null</code> for a <code>null</code> input array.</p>
     * @param array  a <code>Character</code> array, may be <code>null</code>
     * @return a <code>char</code> array, <code>null</code> if null array input
     * @throws NullPointerException if array content is <code>null</code>
     */
    public static char[] toPrimitive(final Character[] array) {
        if (array == null) {
            return null;
        }
        final char[] result = new char[array.length];
        for (int i = 0; i < array.length; i++) {
            Objects.requireNonNull(array[i], "Array content cannot be null");
            result[i] = array[i];
        }
        return result;
    }

    public static void main(String[] args) {
        Character[] charObjects = {'a', 'b', 'c'};
        char[] primitives = toPrimitive(charObjects);
        for (char c : primitives) {
            System.out.println(c);
        }
    }
}
