import java.util.Stack;

public class FrameStackManager {
    private Stack<String> outputFrameStack;

    public FrameStackManager() {
        this.outputFrameStack = new Stack<>();
    }

    /** 
     * Pops as many abstract types from the output frame stack as described by the given descriptor.
     * @param descriptor a type or method descriptor (in which case its argument types are popped).
     */
    private void pop(final String descriptor) {
        if (descriptor == null || descriptor.isEmpty()) {
            return;
        }

        if (descriptor.startsWith("(")) {
            // Method descriptor
            int endIndex = descriptor.indexOf(")");
            if (endIndex != -1) {
                String argumentTypes = descriptor.substring(1, endIndex);
                int index = 0;
                while (index < argumentTypes.length()) {
                    char type = argumentTypes.charAt(index);
                    switch (type) {
                        case 'B': // byte
                        case 'C': // char
                        case 'D': // double
                        case 'F': // float
                        case 'I': // int
                        case 'S': // short
                        case 'Z': // boolean
                            outputFrameStack.pop();
                            index++;
                            break;
                        case 'J': // long
                            outputFrameStack.pop();
                            outputFrameStack.pop(); // long takes two slots
                            index++;
                            break;
                        case 'L': // object
                        case '[': // array
                            int semiColonIndex = argumentTypes.indexOf(';', index);
                            if (semiColonIndex != -1) {
                                outputFrameStack.pop();
                                index = semiColonIndex + 1;
                            } else {
                                index++;
                            }
                            break;
                        default:
                            index++;
                            break;
                    }
                }
            }
        } else {
            // Type descriptor
            switch (descriptor.charAt(0)) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'S': // short
                case 'Z': // boolean
                    outputFrameStack.pop();
                    break;
                case 'J': // long
                    outputFrameStack.pop();
                    outputFrameStack.pop(); // long takes two slots
                    break;
                case 'L': // object
                case '[': // array
