import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class TemplateEncoder {
    /** 
     * Encodes a string with template parameters names present, specifically the characters '{' and '}' will be percent-encoded.
     * @param s the string with zero or more template parameters names
     * @return the string with encoded template parameters names.
     */
    public static String encodeTemplateNames(String s) {
        if (s == null) {
            return null;
        }
        StringBuilder encodedString = new StringBuilder();
        Pattern pattern = Pattern.compile("([{}])");
        Matcher matcher = pattern.matcher(s);
        int lastEnd = 0;
        while (matcher.find()) {
            encodedString.append(s, lastEnd, matcher.start());
            String replacement = matcher.group().equals("{") ? "%7B" : "%7D";
            encodedString.append(replacement);
            lastEnd = matcher.end();
        }
        encodedString.append(s.substring(lastEnd));
        return encodedString.toString();
    }

    public static void main(String[] args) {
        System.out.println(encodeTemplateNames("This is a {template} with {multiple} parameters."));
    }
}
