import java.util.HashMap;
import java.util.Map;

class Node {
    private String id;
    private boolean isVirtual;
    private Node realCounterpart;

    public Node(String id, boolean isVirtual, Node realCounterpart) {
        this.id = id;
        this.isVirtual = isVirtual;
        this.realCounterpart = realCounterpart;
    }

    public String getId() {
        return id;
    }

    public boolean isVirtual() {
        return isVirtual;
    }

    public Node getRealCounterpart() {
        return realCounterpart;
    }
}

class Edge {
    private Node from;
    private Node to;

    public Edge(Node from, Node to) {
        this.from = from;
        this.to = to;
    }

    @Override
    public String toString() {
        return "Edge from " + from.getId() + " to " + to.getId();
    }
}

class Graph {
    private Node currentNode;
    private Map<Node, Node> nodeSequence;

    public Graph() {
        nodeSequence = new HashMap<>();
    }

    public void addNodeSequence(Node from, Node to) {
        nodeSequence.put(from, to);
    }

    public void setCurrentNode(Node node) {
        this.currentNode = node;
    }

    public Edge edgeToNext() {
        Node nextNode = nodeSequence.get(currentNode);
        if (currentNode.isVirtual()) {
            currentNode = currentNode.getRealCounterpart();
        }
        if (nextNode.isVirtual()) {
            nextNode = nextNode.getRealCounterpart();
        }
        return new Edge(currentNode, nextNode);
    }
}

public class Main {
    public static void main(String[] args) {
        Node realNode1 = new Node("1", false, null);
        Node realNode2 = new Node("2", false, null);
        Node virtualNode1 = new Node("v1", true, realNode1);
        Node virtualNode2 = new Node("v2", true, realNode2);

        Graph graph = new Graph();
        graph.addNodeSequence(virtualNode1, virtualNode2);
        graph.setCurrentNode(virtualNode1);

        Edge edge = graph.edgeToNext();
        System.out.println(edge);
    }
}
